import logging

from taf.hw.pdu.devices.ssh_connection import SshConnection


class HAOJIN(SshConnection):

    DEFAULT_PORT = 22

    def __init__(self, host, login, password, port=DEFAULT_PORT):
        super(HAOJIN, self).__init__(
            host=host, login=login, password=password, port=port
        )

    def power_on(self, port):
        logging.debug(f"power on port {port} on HAOJIN")
        return self.send_cmd_and_return_response(f"SW {port} 1\n")

    def power_off(self, port):
        logging.debug(f"power off port {port} on HAOJIN")
        return self.send_cmd_and_return_response(f"SW {port} 0\n")

    def get_port_status(self, port):
        logging.debug(f"get port status {port} on HAOJIN")
        return self.send_cmd_and_return_response("SW\n")

    def _set_port_status(self, port, status):
        """Not implemented due to not supported get_port_status"""

    def _port_setting(self):
        """Not implemented due to not supported get_port_status"""
